CSS Starter:
.chapter { min-height: var(--chapter-height); position: relative; overflow: clip; }
.layer-back { transform: translate3d(0, calc(var(--scroll) * -0.25px), 0); }
@media (prefers-reduced-motion: reduce) { .layer-back { transform: none; } }

.grid { display: grid; grid-template-columns: repeat(var(--grid-cols), 1fr); column-gap: var(--gutter); }
.title { grid-column: 1 / span 8; font-size: clamp(3rem, 9vw, 7rem); line-height: 1; }
.note { grid-column: 9 / span 4; color: var(--muted); }

.panel { background: #05080F; border: 1px solid #19E3FF; color: #D8E6F2; padding: 16px; }
.panel { clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px)); }
.label { font: 12px/1.2 'Share Tech Mono', monospace; letter-spacing: 0.08em; text-transform: uppercase; }

.sprite { image-rendering: pixelated; width: calc(16 * var(--px)); }
.btn { border: var(--border) solid var(--ink); box-shadow: var(--px) var(--px) 0 var(--ink); }
.walk { animation: walk 400ms steps(4) infinite; }

.glass { background: rgba(255 255 255 / 0.12); backdrop-filter: blur(24px) saturate(1.2); border: 1px solid rgb(255 255 255 / 28%); border-radius: 28px; }
.glass:hover { transform: translateY(-6px); transition: transform 250ms ease-out; }
@media (prefers-reduced-transparency: reduce) { .glass { background: #2C2C2E; backdrop-filter: none; } }

body { background: #F1EFE9; color: #1A1A1A; font: 1.2rem/1.6 'Literata', serif; }
main { max-width: 65ch; margin-inline: auto; padding: 4rem 1.25rem; }
a { color: #8A1C1C; text-decoration: underline; text-underline-offset: 0.2em; }

.sticker { transform: rotate(var(--tilt)); box-shadow: 4px 4px 0 #111111; border: 3px solid #111111; }
.sticker:hover { transform: rotate(2deg) scale(1.05); transition: transform 250ms cubic-bezier(.3,1.6,.5,1); }
.reading { background: #FFFFFF; color: #111111; padding: 2rem; }

.shape { border-radius: 60% 40% 55% 45% / 45% 55% 40% 60%; background: #7FA3A0; }
.shape.alt { border-radius: 40% 60% 45% 55% / 55% 45% 60% 40%; transition: border-radius 6s ease-in-out; }
@media (prefers-reduced-motion: reduce) { .shape.alt { transition: none; } }

body { background: #FFFFFF; color: #000000; font: 1.125rem/1.5 'Space Grotesk', sans-serif; }
a { color: #0000EE; text-decoration: underline; }
.box { border: 2px solid #000000; padding: 1rem; margin-block: 1.5rem; }

.btn { background: #E8E4F0; border-radius: 20px; box-shadow: 6px 6px 12px #B9B3CC, -6px -6px 12px #FFFFFF; transition: transform 350ms cubic-bezier(.3,1.5,.5,1); }
.btn:active { transform: scale(0.96); box-shadow: inset 4px 4px 8px #B9B3CC; }
@media (prefers-reduced-motion: reduce) { .btn { transition: none; } }

.section { padding-block: 96px; background: #D9CFB8; color: #2B2A26; }
.section h2 { font-family: 'Lora', serif; color: #4B5B3A; }
.section a { color: #A5673F; text-decoration-thickness: 2px; }

@media (hover: hover) and (pointer: fine) { .cursor { position: fixed; width: 20px; height: 20px; border-radius: 50%; background: #FF4D2E; pointer-events: none; transition: transform 150ms ease-out; } }
.link:focus-visible { outline: 3px solid #FF4D2E; outline-offset: 4px; }
@media (prefers-reduced-motion: reduce) { .cursor { display: none; } }

.prompt { font: 600 1.75rem/1.3 'Atkinson Hyperlegible', sans-serif; color: #F2F5F7; }
.status[data-state='listening'] { color: #3DA5FF; animation: pulse 1200ms ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .status { animation: none; } }

.viewer { height: 70svh; background: #F3F3F1; touch-action: pan-y; }
.viewer:focus-visible { outline: 3px solid #2A5BD7; outline-offset: -3px; }
@media (prefers-reduced-motion: reduce) { .viewer { --rotate-time: 0s; } }

.poster { background: radial-gradient(60% 80% at 20% 20%, #FF6B6B, transparent 70%), radial-gradient(50% 70% at 80% 30%, #FFC857, transparent 70%), #0F1020; }
.poster .text { background: #F7F5FF; color: #0F1020; padding: 2rem; }
@media (prefers-reduced-motion: reduce) { .poster { animation: none; } }

.story { display: grid; grid-template-columns: repeat(12, minmax(0, 1fr)); column-gap: 24px; }
.lead { grid-column: 1 / span 8; }
.lead h1 { font: 700 clamp(2.5rem, 6vw, 5rem)/1.05 'Playfair Display', serif; }
.side { grid-column: 9 / span 4; }

.split { color: #F2F2F2; text-shadow: 2px 0 #FF2A4D, -2px 0 #2AD8FF; }
.split:hover { text-shadow: 4px 0 #FF2A4D, -4px 0 #2AD8FF; transition: text-shadow 200ms ease-out; }
@media (prefers-reduced-motion: reduce) { .split:hover { text-shadow: 2px 0 #FF2A4D, -2px 0 #2AD8FF; } }

.photo { background: #FFFFFF; padding: 14px 14px 48px; box-shadow: 0 2px 8px rgba(59 42 32 / 0.25); transform: rotate(-1.5deg); }
.photo img { filter: sepia(0.2) saturate(0.9) contrast(0.95); display: block; }
.caption { font-family: 'Special Elite', monospace; font-size: 0.9rem; }

.circle { width: 12rem; aspect-ratio: 1; border-radius: 50%; background: #D7261E; }
.bar { height: 2rem; background: #1F4E9C; transform: rotate(-12deg); }
h1 { font: 700 clamp(3rem, 8vw, 6rem)/0.95 'Jost', sans-serif; border-bottom: 4px solid #111111; }

body { background: #FFFFFF; color: #0A0A0A; font: 1.125rem/1.55 'Familjen Grotesk', sans-serif; }
h1 { font-size: clamp(3rem, 8vw, 7rem); line-height: 1; font-weight: 600; }
:focus-visible { outline: 3px solid #0A0A0A; outline-offset: 3px; }

body { background: #F4F1EC; color: #1E1C1A; font: 300 1.0625rem/1.7 'Jost', sans-serif; }
h1, h2 { font-family: 'Cormorant Garamond', serif; font-weight: 300; font-size: clamp(2.5rem, 5vw, 4.5rem); }
.section { padding-block: 144px; max-width: 64rem; margin-inline: auto; }

figure { margin: 0 0 48px; }
figure img { width: 100%; height: auto; display: block; }
figcaption { max-width: 60ch; margin-top: 12px; font: 0.95rem/1.5 'Public Sans', sans-serif; color: #4F4F4F; }
